const results = [];

for (const item of $input.all()) {
  try {
    // 1. Parse the AI's string response into a real JSON object
    const aiData = JSON.parse(item.json.output);

    // 2. Extract the specific fields and attach them directly to the n8n item
    results.push({
      json: {
        category: aiData.category,
        summary: aiData.summary,
        key_points: aiData.key_points,
        importance_score: aiData.importance_score,

        // It is highly recommended to keep the original title and link 
        // so you don't lose them for the next steps!
        title: item.json.title,
        link: item.json.link
      }
    });

  } catch (error) {
    // 3. Fallback: If the AI hallucinates bad JSON, catch the error 
    // so the node doesn't crash for the rest of the good articles.
    results.push({
      json: {
        error: "Failed to parse AI output",
        details: error.message,
        raw_output: item.json.output
      }
    });
  }
}

// 4. Return the new list of neatly separated items
return results;
